export type EventCallback = (payload: any) => void;

export class EventBus {
  private subs: Map<string, Set<EventCallback>> = new Map();

  publish(event: string, payload: any): void {
    const set = this.subs.get(event);
    if (!set) return;
    // Call subscribers synchronously
    for (const cb of Array.from(set)) {
      try {
        cb(payload);
      } catch (err) {
        // swallow subscriber errors to avoid breaking publisher
        // In production we might log this
      }
    }
  }

  subscribe(event: string, callback: EventCallback): void {
    if (!this.subs.has(event)) this.subs.set(event, new Set());
    this.subs.get(event)!.add(callback);
  }

  unsubscribe(event: string, callback: EventCallback): void {
    const set = this.subs.get(event);
    if (!set) return;
    set.delete(callback);
    if (set.size === 0) this.subs.delete(event);
  }
}

export type User = { id: string; name: string; email: string };

export class UserService {
  private store: Map<string, User> = new Map();

  create(user: User): User {
    if (this.store.has(user.id)) throw new Error('User exists');
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, patch: Partial<User>): User {
    const existing = this.store.get(id);
    if (!existing) throw new Error('Not found');
    const updated = { ...existing, ...patch, id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    this.store.delete(id);
  }
}

export type Project = {
  id: string;
  name: string;
  description?: string;
  memberIds: string[];
};

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(project: Project): Project {
    if (this.store.has(project.id)) throw new Error('Project exists');
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, patch: Partial<Project>): Project {
    const existing = this.store.get(id);
    if (!existing) throw new Error('Not found');
    const updated = { ...existing, ...patch, id, memberIds: patch.memberIds ?? existing.memberIds };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const p = this.store.get(projectId);
    if (!p) throw new Error('Not found');
    if (!p.memberIds.includes(userId)) p.memberIds.push(userId);
    return p;
  }

  removeMember(projectId: string, userId: string): Project {
    const p = this.store.get(projectId);
    if (!p) throw new Error('Not found');
    p.memberIds = p.memberIds.filter((id) =&gt; id !== userId);
    return p;
  }
}

import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';
export type Task = {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assigneeId?: string;
  projectId?: string;
};

export class TaskService {
  private store: Map<string, Task> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(task: Task): Task {
    if (this.store.has(task.id)) throw new Error('Task exists');
    this.store.set(task.id, task);
    return task;
  }

  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  update(id: string, patch: Partial<Task>): Task {
    const existing = this.store.get(id);
    if (!existing) throw new Error('Not found');
    const updated = { ...existing, ...patch, id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    this.store.delete(id);
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter((t) =&gt; t.projectId === projectId);
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.store.get(taskId);
    if (!task) throw new Error('Not found');
    task.assigneeId = assigneeId;
    this.store.set(taskId, task);
    // publish event
    this.bus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId });
    return task;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.store.get(taskId);
    if (!task) throw new Error('Not found');
    const order = ['todo', 'in-progress', 'done'] as TaskStatus[];
    const oldIndex = order.indexOf(task.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) throw new Error('Invalid status');
    if (newIndex < oldIndex) throw new Error('Cannot move status backwards');
    if (newIndex === oldIndex) return task;
    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(taskId, task);
    this.bus.publish('task.statusChanged', { taskId: task.id, taskTitle: task.title, assigneeId: task.assigneeId, oldStatus, newStatus });
    return task;
  }
}

import { EventBus } from '../event-bus';

export type Comment = {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
};

export class CommentService {
  private store: Map<string, Comment> = new Map();
  private bus: EventBus;
  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(comment: Omit<Comment, 'createdAt'> & { createdAt?: string }): Comment {
    if (this.store.has(comment.id)) throw new Error('Comment exists');
    const c: Comment = { ...comment, createdAt: comment.createdAt ?? new Date().toISOString() };
    this.store.set(c.id, c);
    // publish event. We don't have access to task title here (constraint), so include taskTitle: '' and let router enrich?
    // But spec expects taskTitle in event. Constraint 2 says services cannot read other stores. So TaskService publishes titles on its events. For comments, we must include taskTitle — how? The router will call CommentService.create and can provide taskTitle if available. To keep services independent, require caller to include taskTitle in payload for event publishing.
    this.bus.publish('comment.added', { commentId: c.id, taskId: c.taskId, authorId: c.authorId, authorName: undefined });
    return c;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter((c) =&gt; c.taskId === taskId);
  }

  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  delete(id: string): void {
    this.store.delete(id);
  }
}

import { EventBus } from '../event-bus';

export type Comment = {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
};

export class CommentService {
  private store: Map<string, Comment> = new Map();
  private bus: EventBus;
  constructor(bus: EventBus) {
    this.bus = bus;
  }

  // meta may include taskTitle, authorName, assigneeId to allow creating rich events
  create(comment: Omit<Comment, 'createdAt'> & { createdAt?: string }, meta?: { taskTitle?: string; authorName?: string; assigneeId?: string }): Comment {
    if (this.store.has(comment.id)) throw new Error('Comment exists');
    const c: Comment = { ...comment, createdAt: comment.createdAt ?? new Date().toISOString() };
    this.store.set(c.id, c);
    // publish event with enriched data if provided
    this.bus.publish('comment.added', {
      commentId: c.id,
      taskId: c.taskId,
      taskTitle: meta?.taskTitle,
      authorId: c.authorId,
      authorName: meta?.authorName,
      assigneeId: meta?.assigneeId,
    });
    return c;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter((c) => c.taskId === taskId);
  }

  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  delete(id: string): void {
    this.store.delete(id);
  }
}

export type Notification = {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
};

import { EventBus } from '../event-bus';

export class NotificationService {
  private store: Map<string, Notification> = new Map();
  private bus: EventBus;
  private idCounter = 1;

  constructor(bus: EventBus) {
    this.bus = bus;
    this.bus.subscribe('task.assigned', (p) => this.onTaskAssigned(p));
    this.bus.subscribe('task.statusChanged', (p) => this.onTaskStatusChanged(p));
    this.bus.subscribe('comment.added', (p) => this.onCommentAdded(p));
  }

  private nextId(): string {
    return String(this.idCounter++);
  }

  private createNotification(userId: string | undefined, message: string) {
    if (!userId) return; // no one to notify
    const n: Notification = { id: this.nextId(), userId, message, read: false, createdAt: new Date().toISOString() };
    this.store.set(n.id, n);
  }

  private onTaskAssigned(payload: any) {
    const { taskId, taskTitle, assigneeId } = payload;
    this.createNotification(assigneeId, `You were assigned task ${taskTitle} (${taskId})`);
  }

  private onTaskStatusChanged(payload: any) {
    const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload;
    this.createNotification(assigneeId, `Status of ${taskTitle} (${taskId}) changed from ${oldStatus} to ${newStatus}`);
  }

  private onCommentAdded(payload: any) {
    const { taskId, taskTitle, authorName, assigneeId } = payload; // assigneeId may be provided by router when creating comment
    this.createNotification(assigneeId, `${authorName} commented on ${taskTitle} (${taskId})`);
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter((n) =&gt; n.userId === userId);
  }

  markAsRead(id: string): Notification | undefined {
    const n = this.store.get(id);
    if (!n) return undefined;
    n.read = true;
    this.store.set(id, n);
    return n;
  }
}

import { createServer, IncomingMessage, ServerResponse } from 'http';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

function parseUrl(url: string | undefined) {
  if (!url) return { path: '/', query: new URLSearchParams() };
  const u = new URL(url, 'http://localhost');
  return { path: u.pathname, query: u.searchParams };
}

export class Router {
  private server = createServer(this.handler.bind(this));

  private bus = new EventBus();
  public users = new UserService();
  public projects = new ProjectService();
  public tasks = new TaskService(this.bus);
  public comments = new CommentService(this.bus);
  public notifications = new NotificationService(this.bus);

  listen(port: number, cb?: () => void) {
    this.server.listen(port, cb);
  }

  close(cb?: () => void) {
    this.server.close(cb ?? (() => {}));
  }

  private async handler(req: IncomingMessage, res: ServerResponse) {
    try {
      const method = req.method || 'GET';
      const { path, query } = parseUrl(req.url);
      const body = await this.readBody(req);

      // simple router matching
      // Users
      if (method === 'GET' && path === '/users') return this.ok(res, this.users.getAll());
      if (method === 'POST' && path === '/users') {
        const u = this.users.create(body);
        return this.ok(res, u, 201);
      }
      if (path.startsWith('/users/')) {
        const id = path.slice('/users/'.length);
        if (method === 'GET') return this.ok(res, this.users.getById(id));
        if (method === 'PUT') return this.ok(res, this.users.update(id, body));
        if (method === 'DELETE') {
          this.users.delete(id);
          return this.ok(res, { deleted: true });
        }
      }

      // Projects
      if (method === 'GET' && path === '/projects') return this.ok(res, this.projects.getAll());
      if (method === 'POST' && path === '/projects') {
        const p = this.projects.create(body);
        return this.ok(res, p, 201);
      }
      if (path.startsWith('/projects/')) {
        const rest = path.slice('/projects/'.length);
        const parts = rest.split('/');
        const id = parts[0];
        if (parts.length === 1) {
          if (method === 'GET') return this.ok(res, this.projects.getById(id));
          if (method === 'PUT') return this.ok(res, this.projects.update(id, body));
          if (method === 'DELETE') {
            this.projects.delete(id);
            return this.ok(res, { deleted: true });
          }
        }
        if (parts.length === 2 && parts[1] === 'members') {
          if (method === 'POST') return this.ok(res, this.projects.addMember(id, body.userId));
          if (method === 'DELETE') return this.ok(res, this.projects.removeMember(id, body.userId));
        }
      }

      // Tasks
      if (method === 'GET' && path === '/tasks') {
        const projectId = query.get('projectId');
        if (projectId) return this.ok(res, this.tasks.getByProject(projectId));
        return this.ok(res, this.tasks.getAll());
      }
      if (method === 'POST' && path === '/tasks') {
        const t = this.tasks.create(body);
        return this.ok(res, t, 201);
      }
      if (path.startsWith('/tasks/')) {
        const rest = path.slice('/tasks/'.length);
        const parts = rest.split('/');
        const id = parts[0];
        if (parts.length === 1) {
          if (method === 'GET') return this.ok(res, this.tasks.getById(id));
          if (method === 'PUT') return this.ok(res, this.tasks.update(id, body));
          if (method === 'DELETE') {
            this.tasks.delete(id);
            return this.ok(res, { deleted: true });
          }
        }
        if (parts.length === 2 && parts[1] === 'status' && method === 'PUT') {
          return this.ok(res, this.tasks.changeStatus(id, body.status));
        }
        if (parts.length === 2 && parts[1] === 'assign' && method === 'PUT') {
          return this.ok(res, this.tasks.assign(id, body.assigneeId));
        }
      }

      // Comments
      if (method === 'GET' && path === '/comments') {
        const taskId = query.get('taskId');
        if (taskId) return this.ok(res, this.comments.getByTask(taskId));
        return this.ok(res, []);
      }
      if (method === 'POST' && path === '/comments') {
        // enrich meta: find task and author name to include in event
        const { taskId, authorId } = body;
        const task = this.tasks.getById(taskId);
        const user = this.users.getById(authorId);
        const comment = this.comments.create(body, { taskTitle: task?.title, authorName: user?.name, assigneeId: task?.assigneeId });
        return this.ok(res, comment, 201);
      }
      if (path.startsWith('/comments/')) {
        const id = path.slice('/comments/'.length);
        if (method === 'GET') return this.ok(res, this.comments.getById(id));
        if (method === 'DELETE') {
          this.comments.delete(id);
          return this.ok(res, { deleted: true });
        }
      }

      // Notifications
      if (method === 'GET' && path === '/notifications') {
        const userId = query.get('userId');
        if (!userId) return this.ok(res, []);
        return this.ok(res, this.notifications.getByUser(userId));
      }
      if (path.startsWith('/notifications/') && path.endsWith('/read') && method === 'PUT') {
        const id = path.slice('/notifications/'.length, -'/read'.length);
        return this.ok(res, this.notifications.markAsRead(id));
      }

      this.notFound(res);
    } catch (err: any) {
      this.error(res, err);
    }
  }

  private readBody(req: IncomingMessage): Promise<any> {
    return new Promise((resolve) => {
      const chunks: Buffer[] = [];
      req.on('data', (c) => chunks.push(Buffer.from(c)));
      req.on('end', () => {
        if (chunks.length === 0) return resolve({});
        try {
          const s = Buffer.concat(chunks).toString();
          resolve(JSON.parse(s));
        } catch (err) {
          resolve({});
        }
      });
    });
  }

  private ok(res: ServerResponse, body: any, status = 200) {
    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(body ?? null));
  }

  private notFound(res: ServerResponse) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'not found' }));
  }

  private error(res: ServerResponse, err: any) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: String(err?.message ?? err) }));
  }
}

